class Solution {
public:
    vector<int> relativeSortArray(vector<int>& arr1, vector<int>& arr2) {
        vector<int> count(1001, 0);
        for (int x : arr1) count[x]++;
        vector<int> res;
        res.reserve(arr1.size());
        for (int x : arr2) {
            while (count[x] > 0) {
                res.push_back(x);
                count[x]--;
            }
        }
        for (int x = 0; x <= 1000; ++x) {
            while (count[x] > 0) {
                res.push_back(x);
                count[x]--;
            }
        }
        return res;
    }
};

class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        int[] count = new int[1001];
        for (int x : arr1) count[x]++;
        int[] res = new int[arr1.length];
        int idx = 0;
        for (int x : arr2) {
            while (count[x] > 0) {
                res[idx++] = x;
                count[x]--;
            }
        }
        for (int x = 0; x <= 1000; x++) {
            while (count[x] > 0) {
                res[idx++] = x;
                count[x]--;
            }
        }
        return res;
    }
}

